-- IELTS(雅思)词库迁移:0 → 4321 词 × 3 active 课程 = 12963 word 行
-- 词表来源:lzrknglsh IELTS-4000.txt (4321 词)
-- 字段策略:与 KET/TOEIC/PEP 重叠词 → 复用已有 lexeme tuple(共享 lexeme_id);净新词 LLM 生成
-- 学术/教育/科技/社会场景,A2-B2 难度,5-20 词例句
-- 幂等:courses WHERE NOT EXISTS;lexicon ON CONFLICT DO NOTHING;words WHERE NOT EXISTS

-- 1. 插入 雅思 × 9 method = 9 课程行(朗读/学习/测评 active)
INSERT INTO courses (id, subject, textbook, learning_method, default_points, is_active, sort_order, created_at, updated_at)
SELECT gen_random_uuid(), '英语', '雅思', v.method, v.points, v.is_active, v.sort_order, now(), now()
FROM (VALUES
('雅思', '朗读', 5, TRUE, 380),
('雅思', '学习', 5, TRUE, 381),
('雅思', '测评', 15, TRUE, 382),
('雅思', '背诵', 5, FALSE, 383),
('雅思', '听力', 5, FALSE, 384),
('雅思', '口语', 10, FALSE, 385),
('雅思', '写作', 10, FALSE, 386),
('雅思', '授课', 10, FALSE, 387),
('雅思', '测试', 15, FALSE, 388)
) AS v(textbook, method, points, is_active, sort_order)
WHERE NOT EXISTS (SELECT 1 FROM courses c WHERE c.subject='英语' AND c.textbook=v.textbook AND c.learning_method=v.method);

-- 2. 激活 雅思·朗读/学习/测评 三门
UPDATE courses SET is_active = TRUE, updated_at = NOW()
WHERE subject = '英语' AND textbook = '雅思' AND learning_method IN ('朗读', '学习', '测评') AND is_active = FALSE;

