-- 4. 给 雅思 3 门 active 课插词(共享 lexeme_id)
INSERT INTO words (id, course_id, lexeme_id, spelling, syllables, meaning_cn, phonetic,
                   sample_sentence, sample_sentence_translation, sort_order, is_active, created_at, updated_at)
SELECT gen_random_uuid(), c.id, l.id, v.spelling, v.syllables::jsonb, v.meaning_cn, v.phonetic,
       v.sample_sentence, v.sample_sentence_translation, v.sort_order, TRUE, now(), now()
