('correlate', '["cor", "re", "late"]', '相关,关联', '/ˈkɒr.ə.leɪt/', 'Studies show that education levels correlate closely with income earned.', '研究表明,教育水平与收入密切相关。', 936),
('correlation', '["cor", "re", "la", "tion"]', '相关性,关联', '/ˌkɒr.əˈleɪ.ʃən/', 'Researchers found a strong correlation between diet and heart disease.', '研究人员发现饮食与心脏病之间有很强的相关性。', 937),
