('propagate', '["prop", "a", "gate"]', '传播;繁殖;宣传', '/ˈprɒp.ə.ɡeɪt/', 'The IT team propagated the new security settings across all branch offices.', 'IT 团队把新的安全设置推广到了所有分公司。', 3082),
