('whereby', '["where", "by"]', '凭此;借以;通过', '/weəˈbaɪ/', 'The company created a new system whereby employees could work remotely.', '公司建立了一个新系统,员工可以远程工作。', 4270),
('whilst', '["whilst"]', '当……时;然而;虽然', '/waɪlst/', 'She read a book whilst waiting for her flight at the airport.', '她在机场等航班时读了一本书。', 4271),
('whip', '["whip"]', '鞭子;鞭打;搅打', '/wɪp/', 'The chef used a whisk to whip cream for the dessert topping quickly.', '厨师用打蛋器快速搅打奶油做甜点装饰。', 4272),
('whirl', '["whirl"]', '旋转;回旋;急走', '/wɜːl/', 'Autumn leaves whirled in the strong wind across the empty courtyard.', '秋叶在强风中在空荡的庭院里旋转。', 4273),
('whisper', '["whis", "per"]', '低语;耳语;微弱声响', '/ˈwɪs.pər/', 'She whispered a secret into her best friend''s ear during the lesson.', '她在上课时对好朋友耳语了一个秘密。', 4274),
('whistle', '["whis", "tle"]', '口哨;哨子;呼啸', '/ˈwɪs.əl/', 'The referee blew his whistle loudly to signal the end of the match.', '裁判大声吹响哨子,示意比赛结束。', 4275),
('wholesale', '["whole", "sale"]', '批发;批发的', '/ˈhəʊl.seɪl/', 'We buy all office paper at wholesale prices.', '我们以批发价购买所有办公用纸。', 4276),
('wholesaler', '["whole", "saler"]', '批发商;分销商', '/ˈhəʊl.seɪ.lər/', 'The retailer ordered five hundred shirts from a local wholesaler last week.', '零售商上周从当地批发商处订购了五百件衬衫。', 4277),
('wholesome', '["whole", "some"]', '有益健康的;健全的', '/ˈhəʊl.səm/', 'The restaurant serves wholesome meals made with fresh local vegetables.', '这家餐厅供应用新鲜本地蔬菜制作的健康餐点。', 4278),
('wicked', '["wicked"]', '邪恶的;恶劣的;淘气的', '/ˈwɪk.ɪd/', 'The wicked witch cast a terrible spell on the innocent young prince.', '邪恶的女巫对无辜的年轻王子施了可怕的咒语。', 4279),
('widespread', '["wide", "spread"]', '广泛的;普遍的', '/ˈwaɪd.spred/', 'The outage caused widespread disruption to online services.', '这次故障造成在线服务大范围中断。', 4280),
('width', '["width"]', '宽度;广度;宽阔', '/wɪdθ/', 'The river reaches its greatest width during the spring rainy season.', '这条河在春雨季节达到最宽。', 4281),
('wield', '["wield"]', '挥舞;行使;掌握', '/wiːld/', 'The king continued to wield enormous power over his loyal subjects.', '国王继续对忠诚的臣民行使巨大权力。', 4282),
('wilderness', '["wilder", "ness"]', '荒野;旷野;茫茫一片', '/ˈwɪl.də.nəs/', 'Hikers got lost in the vast wilderness of the northern mountains for days.', '徒步旅行者在北部山脉的广阔荒野中迷路了好几天。', 4283),
('willow', '["wil", "low"]', '柳树;柳木', '/ˈwɪl.əʊ/', 'A tall willow stood gracefully by the edge of the quiet lake.', '一棵高大的柳树优雅地矗立在宁静的湖边。', 4284),
('winding', '["wind", "ing"]', '蜿蜒的;弯曲的;卷绕的', '/ˈwaɪn.dɪŋ/', 'The car slowly climbed the winding road up the steep mountain side.', '汽车缓缓爬上陡峭山边的蜿蜒道路。', 4285),
('wisdom', '["wis", "dom"]', '智慧;明智;学问', '/ˈwɪz.dəm/', 'Grandparents often share their wisdom with the younger family generations.', '祖父母经常与年轻一代分享他们的智慧。', 4286),
('wit', '["wit"]', '机智;才智;幽默感', '/wɪt/', 'The famous writer was known for his sharp wit and clever humor everywhere.', '这位著名作家以敏锐的机智和聪明的幽默著称。', 4287),
('withdraw', '["with", "draw"]', '提取;撤回', '/wɪðˈdrɔː/', 'He decided to withdraw his application before the interview.', '他决定在面试前撤回申请。', 4288),
('withdrawal', '["with", "draw", "al"]', '提款;撤回', '/wɪðˈdrɔː.əl/', 'The bank charges a fee for each overseas withdrawal.', '银行对每笔海外取款收取手续费。', 4289),
('wither', '["with", "er"]', '枯萎;凋谢;衰退', '/ˈwɪð.ər/', 'The flowers will quickly wither without enough water and warm sunlight.', '没有足够的水和温暖的阳光,花朵会很快枯萎。', 4290),
('withhold', '["with", "hold"]', '扣留;拒绝给予', '/wɪðˈhəʊld/', 'The client decided to withhold payment until repairs were done.', '客户决定扣留货款，直到维修完成。', 4291),
('withstand', '["with", "stand"]', '经受;承受;抵住', '/wɪðˈstænd/', 'The old bridge can withstand heavy trucks and severe storms without damage.', '这座旧桥能承受重型卡车和猛烈风暴而不受损。', 4292),
('witness', '["wit", "ness"]', '目击;见证;证人', '/ˈwɪt.nəs/', 'Two managers witnessed the signing of the agreement.', '两位经理见证了协议的签署。', 4293),
('woe', '["woe"]', '悲哀;苦恼;灾难', '/wəʊ/', 'She told her friend her tales of woe after a long difficult week.', '在漫长艰难的一周后,她向朋友诉说了自己的苦恼。', 4294),
('woods', '["woods"]', '树林;森林;林地', '/wʊdz/', 'The children loved exploring the woods behind their grandparents'' old house.', '孩子们喜欢探索祖父母旧房子后面的树林。', 4295),
('wool', '["wool"]', '羊毛', '/wʊl/', 'The scarf is made of wool.', '这条围巾是羊毛做的。', 4296),
('wording', '["word", "ing"]', '措辞;用词;表达方式', '/ˈwɜː.dɪŋ/', 'The lawyer suggested changing the wording of the contract''s final clause.', '律师建议修改合同最后条款的措辞。', 4297),
('worldwide', '["world", "wide"]', '全世界的;世界范围的', '/ˌwɜːldˈwaɪd/', 'The company now operates a worldwide network of retail stores and suppliers.', '该公司现在运营着全球范围的零售店和供应商网络。', 4298),
('worst', '["worst"]', '最糟的', '/wɜːst/', 'That was the worst film ever.', '那是有史以来最糟的电影。', 4299),
('worthwhile', '["worth", "while"]', '值得的;有价值的', '/ˌwɜːθˈwaɪl/', 'Studying abroad can be a very worthwhile experience for young students.', '出国留学对年轻学生来说是非常有价值的经历。', 4300),
('wrap', '["wrap"]', '包裹;完成', '/ræp/', 'Please wrap the fragile items before shipping them.', '请在发货前把易碎物品包好。', 4301),
('wrath', '["wrath"]', '愤怒;狂怒;暴怒', '/rɒθ/', 'The king''s wrath fell upon the traitors who had betrayed his trusted kingdom.', '国王的愤怒降临到那些背叛他信任的王国的叛徒身上。', 4302),
('wreck', '["wreck"]', '残骸;破坏;失事', '/rek/', 'Divers discovered the wreck of an ancient ship beneath the blue sea.', '潜水员在蔚蓝的海水下发现了一艘古船的残骸。', 4303),
('wrench', '["wrench"]', '扳手;猛扭;痛苦', '/rentʃ/', 'The mechanic used a wrench to tighten the loose bolts on the wheel.', '机械师用扳手拧紧车轮上松动的螺栓。', 4304),
('wrestle', '["wres", "tle"]', '摔跤;搏斗;斟酌', '/ˈres.əl/', 'The two boys decided to wrestle in the backyard after school today.', '两个男孩决定今天放学后在后院摔跤。', 4305),
('wretched', '["wretch", "ed"]', '可怜的;悲惨的;恶劣的', '/ˈretʃ.ɪd/', 'The wretched refugees had no food or shelter during the long cold winter.', '可怜的难民在漫长寒冷的冬天没有食物和住所。', 4306),
('wring', '["wring"]', '拧;绞;榨取', '/rɪŋ/', 'She had to wring the wet towel before hanging it outside.', '她得先把湿毛巾拧干,再挂到外面。', 4307),
('wrinkle', '["wrin", "kle"]', '皱纹;皱褶', '/ˈrɪŋ.kəl/', 'Iron your shirt to remove the wrinkles before the meeting.', '开会前把衬衫的皱褶熨平。', 4308),
('wrist', '["wrist"]', '手腕;腕关节', '/rɪst/', 'She injured her wrist while playing tennis at the local sports club.', '她在当地俱乐部打网球时手腕受伤了。', 4309),
('yacht', '["yacht"]', '游艇;帆船;快艇', '/jɒt/', 'The wealthy businessman sailed his luxury yacht around the Mediterranean Sea.', '这位富商驾驶豪华游艇环游地中海。', 4310),
('yard', '["yard"]', '院子;码;庭院', '/jɑːd/', 'The children played happily in the front yard of their house all afternoon.', '孩子们整个下午都在房子前院快乐地玩耍。', 4311),
('yawn', '["yawn"]', '打哈欠;哈欠;裂口', '/jɔːn/', 'The tired student couldn''t stop yawning during the long boring lecture.', '疲惫的学生在漫长无聊的讲座中不停地打哈欠。', 4312),
('yearn', '["yearn"]', '渴望;向往;思念', '/jɜːn/', 'She often yearned for the peaceful countryside after moving to town.', '搬到城里后她常常向往宁静的乡村。', 4313),
('yeast', '["yeast"]', '酵母;酵母菌;泡沫', '/jiːst/', 'The baker added fresh yeast to the dough to make it rise properly.', '面包师在面团中加入新鲜酵母使其适当发酵。', 4314),
('yield', '["yield"]', '产出;收益;让步', '/jiːld/', 'The investment yielded a ten percent return last year.', '这项投资去年产生了百分之十的回报。', 4315),
('yoke', '["yoke"]', '枷锁;束缚;羁绊', '/jəʊk/', 'The oxen were tied together with a heavy wooden yoke to pull plows.', '牛被沉重的木枷锁系在一起拉犁。', 4316),
('yolk', '["yolk"]', '蛋黄;卵黄', '/jəʊk/', 'She carefully separated the egg yolk from the white for her cake recipe.', '她小心地把蛋黄和蛋白分开来做蛋糕。', 4317),
('zeal', '["zeal"]', '热情;热忱;狂热', '/ziːl/', 'The young teacher approached her new job with great zeal and enthusiasm.', '这位年轻教师以极大的热情投入她的新工作。', 4318),
('zealous', '["zeal", "ous"]', '热心的;热忱的', '/ˈzel.əs/', 'A zealous sales team can double annual revenue.', '一支充满热忱的销售团队可以让年收入翻倍。', 4319),
('zone', '["zone"]', '区域;地带', '/zəʊn/', 'The factory is located in a special economic zone.', '工厂位于一个经济特区内。', 4320),
('zoology', '["zo", "ol", "o", "gy"]', '动物学;动物学课程', '/zuˈɒl.ə.dʒi/', 'She decided to study zoology because she truly loved all kinds of animals.', '她决定学习动物学,因为她真心喜欢各种动物。', 4321)
) AS v(spelling, syllables, meaning_cn, phonetic, sample_sentence, sample_sentence_translation, sort_order)
JOIN courses c ON c.subject = '英语' AND c.textbook = '雅思'
                AND c.learning_method IN ('朗读', '学习', '测评') AND c.is_active = TRUE
JOIN lexicon l ON l.spelling = v.spelling
WHERE NOT EXISTS (SELECT 1 FROM words x WHERE x.course_id = c.id AND x.spelling = v.spelling);
